// แยก UGC Script จาก GPT และเตรียม Veo 3 request
const gptRaw = $('GPT เขียน UGC Script').first().json;
const rawText = gptRaw.output?.[0]?.content?.[0]?.text || gptRaw.message?.content || '';
const cleaned = rawText.replace(/^```json\n?/i,'').replace(/^```\n?/i,'').replace(/\n?```$/i,'').trim();

let script = {};
try {
  script = JSON.parse(cleaned);
} catch(e) {
  console.log('Parse error, using fallback:', e.message);
  const sheet = $('เตรียมข้อมูล').first().json;
  script = {
    thaiScript: `ลองแล้วบอกเลย ${(sheet['product_name']||'').replace(/^=+/,'').trim()} คุ้มมากเลยนะ จุดเด่นชัดมาก ดูรีวิวเต็มที่ KaoShop ได้เลย`,
    videoDirection: `Young Thai woman presenter reviewing a product, holding it up to camera, smiling naturally, bright clean background`
  };
}

const sheet = $('เตรียมข้อมูล').first().json;
const productName = (sheet['product_name'] || '').replace(/^=+/, '').trim();
const img1 = $('แปลงรูป Cloudinary1').first().json?.secure_url || '';

// สร้าง Veo 3 prompt: รวม video direction + Thai dialogue
const videoPrompt = [
  script.videoDirection,
  `She looks at the camera and speaks naturally in Thai: "${script.thaiScript}"`,
  'Generate with native Thai audio and perfect lip sync.',
  'Bright professional lighting, 16:9 aspect ratio, UGC style, cinematic quality.'
].join(' ');

console.log(`UGC Script สำหรับ: ${productName}`);
console.log(`Thai Script: ${script.thaiScript}`);
console.log(`Image URL: ${img1}`);

return [{
  json: {
    thaiScript: script.thaiScript,
    videoPrompt,
    imageUrl: img1,
    productName
  }
}];

